+        ($3, 'Hidden', 'Applicant', $4, null, null, 'provisioning', 'unused', now() + interval '1 day')`,
+      [verifiedId, `verified-${suffix}@example.test`, hiddenId, `hidden-${suffix}@example.test`],
+    );
+
+    await page.goto("/review");
